mapper.select:
/** * selectAttdneMngList : isry.couns.mngr.workaltmntmng.mapper.AttdneMngMapper : 근태관리 목록 조회 */ SELECT AA.CONSTT_ID AS CNSLTNT_ID /** 상담사 아이디 **/ , C##RG.DEC_B64(DD.FLNM_ENCPT) AS CNSLTNT_NM /** 상담사 이름 **/ , AA.WORK_YMD AS WORK_YMD /** 근무일자 **/ , NVL(AA.ATENDB_HR, '결근') AS WORK_HR /** 출근시간 **/ , AA.LATEN_HR AS LATEN_HR /** 지각시간 **/ , AA.EXCL_HR AS EXCL_HR /** 차감시간 **/ , AA.DCLZ_MNG_PEPO_SCORE AS DCLZ_MNG_PEPO_SCORE /** 벌점 **/ , AA.PROBM_BASIS_CN AS PROBM_BASIS_CN /** 사유 **/ FROM AYC440 AA /** 근태관리 **/ , SAA200 CC /** 사용자 **/ , SCA100 DD /** 종사자 **/ WHERE 1=1 AND AA.CONSTT_ID = CC.USER_ID AND CC.ENFSN_NO = DD.ENFSN_NO
AND DD.OGDP_DEPT_CD = #{deptCd}
AND AA.WORK_YMD LIKE #{crtrYm}||'%'
ORDER BY 1,3

mapper.insert:
/**
*		insertAttdneMng : isry.couns.mngr.workaltmntmng.mapper.AttdneMngMapper : 근태관리 행추가
*/
	INSERT INTO
			AYC440		/** 근태관리 데이터 **/
			(					
					CONSTT_ID				/** 상담사아이디 **/
				,	WORK_YMD				/** 근무일자 **/
				,	ATENDB_HR				/** 출근시간 **/
				,	LATEN_HR				/** 지각시간 **/
				,	EXCL_HR					/** 제외시간 **/
				,	DCLZ_MNG_PEPO_SCORE		/** 근태관리벌점점수 **/
				,	PROBM_BASIS_CN			/** 문제근거내용 **/
				,	FRST_RGTR_ID
				,	FRST_REG_DT
				,	LAST_MDFR_ID
				,	LAST_MDFCN_DT
			)
	VALUES
			(
					#{CNSLTNT_ID}
				,	#{WORK_YMD}
				,	#{WORK_HR}
				,	#{LATEN_HR}
				,	#{EXCL_HR}
				,	#{DCLZ_MNG_PEPO_SCORE}
				,	#{PROBM_BASIS_CN}
				,	#{loginId}
				,	SYSDATE
				,	#{loginId}
				,	SYSDATE
			)

mapper.delete:
/**
*		deleteAttdneMng : isry.couns.mngr.workaltmntmng.mapper.AttdneMngMapper : 근태관리 행삭제
*/
	DELETE
	FROM
			AYC440		/** 근태관리 데이터 **/
	WHERE	1=1
		AND	WORK_YMD		=	#{WORK_YMD}
		AND	CONSTT_ID	=	#{CNSLTNT_ID}

mapper.update:
/* SQL-ID : isry.couns.mngr.workaltmntmng.mapper.AttdneMngMapper.processAttdneMngMonth : 근태관리 월 데이터 처리 */ MERGE INTO AYC440 A /** 근태관리 데이터 */ USING ( WITH VIEW_CNSLTNT_WORK_SCHDL AS (
) , VIEW_VCATN_APLY_HISTB AS (
) SELECT R1.WORK_YMD /* 근무일자 */ , R1.CNSLTNT_ID /* 상담자아이디 */ , R1.ATENDB_HR /* 출근시간 */ , R1.LATEN_HR /* 지각시각(분) */ , R1.EXCL_YMD /* 제외일자 */ , R1.EXCL_HR /* 제외시간 - 차감시간 */ , R1.DCLZ_MNG_PEPO_SCORE /* 근태관리 벌점점수 */ , R1.PROBM_BASIS_CN /* 문제근거내용 */ , R1.PROBM_BASIS_ETC_CN /* 문제근거기타내용 */ FROM ( SELECT T1.WORK_YMD AS WORK_YMD , T1.CNSLTNT_ID AS CNSLTNT_ID , TO_CHAR(T2.ATENDB_DT, 'HH24:MI') AS ATENDB_HR , NVL(C##RG.SA_FN_DATEDIFF('MI', T1.WORK_BGNG_DT, T2.ATENDB_DT), 0) AS LATEN_HR , '' AS EXCL_YMD , 0 AS EXCL_HR
, CASE WHEN ATENDB_DT IS NULL THEN 3 ELSE CASE WHEN C##RG.SA_FN_DATEDIFF('MI', T1.WORK_BGNG_DT, T2.ATENDB_DT) < 10 THEN 1 ELSE 2 END END AS DCLZ_MNG_PEPO_SCORE
, '' AS PROBM_BASIS_CN , '' AS PROBM_BASIS_ETC_CN FROM VIEW_CNSLTNT_WORK_SCHDL T1 , AYC495 T2 WHERE 1=1
AND T1.WORK_YMD BETWEEN #{SCHDL_BGNG_YMD} AND #{SCHDL_END_YMD}
AND T1.WORK_YMD >= #{SCHDL_BGNG_YMD} AND T1.WORK_END_DT <= SYSDATE
AND NOT EXISTS ( SELECT * FROM VIEW_VCATN_APLY_HISTB T3 WHERE 1=1 AND T3.USER_ID = T1.CNSLTNT_ID AND T1.WORK_YMD BETWEEN T3.VCATN_BGNG_YMD AND T3.VCATN_END_YMD ) AND NOT EXISTS ( SELECT * FROM AYC440 T4 WHERE 1=1 AND T4.CONSTT_ID = T1.CNSLTNT_ID AND T4.WORK_YMD = T1.WORK_YMD AND T4.ATENDB_HR IS NOT NULL ) AND T1.WORK_YMD = T2.WORK_YMD(+) AND T1.CNSLTNT_ID = T2.CONSTT_ID(+) ) R1 WHERE 1=1 AND (
R1.ATENDB_HR IS NULL OR R1.LATEN_HR > 0
) ) B ON ( A.WORK_YMD = B.WORK_YMD /* 근무일자 */ AND A.CONSTT_ID = B.CNSLTNT_ID /* 상담사아이디 */ ) WHEN MATCHED THEN UPDATE SET A.ATENDB_HR = B.ATENDB_HR, A.LATEN_HR = B.LATEN_HR, A.EXCL_YMD = B.EXCL_YMD, A.EXCL_HR = B.EXCL_HR, A.DCLZ_MNG_PEPO_SCORE = B.DCLZ_MNG_PEPO_SCORE, A.PROBM_BASIS_CN = B.PROBM_BASIS_CN, A.PROBM_BASIS_ETC_CN = B.PROBM_BASIS_ETC_CN, A.LAST_MDFR_ID = #{RGTR_ID}, A.LAST_MDFCN_DT = SYSDATE WHEN NOT MATCHED THEN INSERT ( A.WORK_YMD , A.CONSTT_ID , A.ATENDB_HR , A.LATEN_HR , A.EXCL_YMD , A.EXCL_HR , A.DCLZ_MNG_PEPO_SCORE , A.PROBM_BASIS_CN , A.PROBM_BASIS_ETC_CN , A.FRST_RGTR_ID , A.FRST_REG_DT , A.LAST_MDFR_ID , A.LAST_MDFCN_DT ) VALUES ( B.WORK_YMD , B.CNSLTNT_ID , B.ATENDB_HR , B.LATEN_HR , B.EXCL_YMD , B.EXCL_HR , B.DCLZ_MNG_PEPO_SCORE , B.PROBM_BASIS_CN , B.PROBM_BASIS_ETC_CN , #{RGTR_ID} , SYSDATE , #{RGTR_ID} , SYSDATE )
